#!/data/data/com.termux/files/usr/bin/bash
# ============================================================================
# Start, stop and inspect code-server on Termux
# Generated by tpf from src/code-server-ctl/ - do not edit, run ./tpf build.
# code-server-ctl 1.0 (sources sha256:ed85729e802a602c)
# ============================================================================
# shellcheck disable=SC2034  # available to the script, not always used
TPF_NAME=code-server-ctl
TPF_VERSION=1.0
TPF_SOURCE_HASH=ed85729e802a602c
# ============================================================================
# code-server.sh — manage code-server on Termux
#
#   ./code-server.sh start      start the server
#   ./code-server.sh stop       stop it
#   ./code-server.sh restart    stop, then start
#   ./code-server.sh status     tell whether it is running
#   ./code-server.sh log [n]    follow the log (last n lines, default 50)
#
# Settings: code-server.conf next to this script (or the file in $CS_CONF).
# ============================================================================
set -uo pipefail

SELF="$(readlink -f "${BASH_SOURCE[0]}" 2>/dev/null || printf '%s' "${BASH_SOURCE[0]}")"
CONF="${CS_CONF:-$(dirname "$SELF")/code-server.conf}"

# --- Defaults (used when the settings file is missing or incomplete) -------
CS_PORT=8080
CS_IP=127.0.0.1
CS_AUTH=none
CS_PASSWORD=""
CS_LOG_LINES=25
CS_START_TIMEOUT=45
CS_START_RETRIES=2
CS_BIN=""
CS_LOG_FILE="$HOME/.code-server.log"
CS_PID_FILE="$HOME/.code-server.pid"
CS_CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/code-server"
CS_DATA_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/code-server"
CS_LINUX_SPOOF=0
CS_MS_MARKETPLACE=0
CS_ROOT_INOTIFY=0
CS_INOTIFY_WATCHES=524288
CS_ROOT_HELPER=""
CS_EXTRA_ARGS=""

# --- tpf: begin src/lib/core.sh ---
# Basics shared by every installer: checks, clean exit, signals, wake lock.
#
# Commands: have is_uint is_port require_termux require_aarch64
#           on_exit wake_lock
# --- tpf: begin src/lib/ui.sh ---
# Output style shared by every installer (see docs/STYLE.md).
#
#   [INFO] [ OK ] [ ?? ] [WARN]    six columns: the text always starts at column 8
#   [ERROR]                        danger: seven columns, written to stderr
#   [.   ] [..  ] [... ] ...       a task that is running (see task)
#
# Commands: info ok warn err detail step banner die
#           ask_yes_no ask_input ask_choice task
# Variable: TPF_ASSUME=yes|no answers every question without asking.

_UI_FRAMES=('[.   ]' '[..  ]' '[... ]' '[ ...]' '[  ..]' '[   .]')
_UI_CURSOR_HIDDEN=0
_TASK_PID=""

# ui_colors on|off|auto
ui_colors() {
    local mode="${1:-auto}"
    if [ "$mode" = auto ]; then
        if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-}" != dumb ]; then mode=on; else mode=off; fi
    fi
    if [ "$mode" = on ]; then
        C_RESET=$'\033[0m'; C_BOLD=$'\033[1m'; C_DIM=$'\033[2m'
        C_INFO=$'\033[1;34m'; C_OK=$'\033[1;32m'; C_WARN=$'\033[1;33m'
        C_ERR=$'\033[1;31m'; C_ASK=$'\033[1;36m'
    else
        C_RESET=""; C_BOLD=""; C_DIM=""
        C_INFO=""; C_OK=""; C_WARN=""; C_ERR=""; C_ASK=""
    fi
}
ui_colors auto

# True when a running task can be animated in place.
_ui_animated() {
    [ -t 1 ] && [ "${TERM:-}" != dumb ] && [ -z "${TPF_NO_ANIM:-}" ]
}

# Everything printed is also appended, without colours, to $TPF_LOG_DIR/run.log.
_ui_log() {
    [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ] || return 0
    printf '%s %-5s %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$1" "$2" >>"$TPF_LOG_DIR/run.log" 2>/dev/null || true
}

_ui_line() {   # colour tag text
    printf '%s%s%s %s\n' "$1" "$2" "$C_RESET" "$3"
}

info() { _ui_line "$C_INFO" '[INFO]' "$*"; _ui_log INFO "$*"; }
ok()   { _ui_line "$C_OK" '[ OK ]' "$*"; _ui_log OK "$*"; }
warn() { _ui_line "$C_WARN" '[WARN]' "$*"; _ui_log WARN "$*"; }
err()  { _ui_line "$C_ERR" '[ERROR]' "$*" >&2; _ui_log ERROR "$*"; }

# A dimmed line aligned with the text of the lines above.
detail() { printf '       %s%s%s\n' "$C_DIM" "$*" "$C_RESET"; }

step() {
    printf '\n%s=== %s ===%s\n' "$C_INFO" "$*" "$C_RESET"
    _ui_log STEP "$*"
}

# banner TITLE [SUBTITLE]
banner() {
    local bar="============================================================"
    printf '\n%s%s\n %s\n' "$C_OK" "$bar" "$1"
    [ -z "${2:-}" ] || printf ' %s\n' "$2"
    printf '%s%s\n' "$bar" "$C_RESET"
}

die() {
    err "$*"
    if [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ]; then
        printf '       %sLogs: %s%s\n' "$C_DIM" "$TPF_LOG_DIR" "$C_RESET" >&2
    fi
    exit 1
}

# ---------------------------------------------------------------------------
# Questions. They read /dev/tty, so they also work with `curl ... | bash`.
# The answer of ask_input / ask_choice is left in $ANSWER.
# ---------------------------------------------------------------------------
_ui_have_tty() { ( : </dev/tty ) 2>/dev/null; }

_ui_prompt() {   # text; reads one line from the terminal into $_UI_REPLY
    _UI_REPLY=""
    printf '%s[ ?? ]%s %s' "$C_ASK" "$C_RESET" "$1" >/dev/tty
    IFS= read -r _UI_REPLY </dev/tty || _UI_REPLY=""
}

# ask_yes_no "question" [yes|no]   -> status 0 for yes
ask_yes_no() {
    local question="$1" def="${2:-no}" hint
    case "${TPF_ASSUME:-}" in
        yes) _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: yes]${C_RESET}"; return 0 ;;
        no)  _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: no]${C_RESET}"; return 1 ;;
    esac
    if [ "$def" = yes ]; then hint="[Y/n]"; else hint="[y/N]"; fi
    if _ui_have_tty; then
        _ui_prompt "$question $hint "
        case "$_UI_REPLY" in
            y|Y|yes|Yes|YES|o|O|oui|Oui|OUI) return 0 ;;
            n|N|no|No|NO|non|Non|NON) return 1 ;;
            *) [ "$def" = yes ]; return ;;
        esac
    fi
    warn "No terminal available: default answer \"$def\" used ($question)"
    [ "$def" = yes ]
}

# ask_input "question" "default"   -> $ANSWER
ask_input() {
    local question="$1" def="${2:-}"
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ]; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: ${def:-empty}]${C_RESET}"
        return 0
    fi
    if _ui_have_tty; then
        _ui_prompt "$question${def:+ [$def]} "
        [ -z "$_UI_REPLY" ] || ANSWER="$_UI_REPLY"
        return 0
    fi
    warn "No terminal available: default \"${def:-empty}\" used ($question)"
}

# ask_choice "question" DEFAULT option...   -> $ANSWER (one of the options)
ask_choice() {
    local question="$1" def="$2" opt n=0
    shift 2
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ] || ! _ui_have_tty; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: $def]${C_RESET}"
        return 0
    fi
    _ui_line "$C_ASK" '[ ?? ]' "$question"
    for opt in "$@"; do
        n=$((n + 1))
        printf '       %s%d)%s %s%s\n' "$C_BOLD" "$n" "$C_RESET" "$opt" "$([ "$opt" = "$def" ] && printf ' (default)')"
    done
    _ui_prompt "Choice [1-$n or name] "
    n=0
    for opt in "$@"; do
        n=$((n + 1))
        if [ "$_UI_REPLY" = "$n" ] || [ "$_UI_REPLY" = "$opt" ]; then ANSWER="$opt"; return 0; fi
    done
    [ -z "$_UI_REPLY" ] || warn "\"$_UI_REPLY\" is not an option: default \"$def\" used"
}

# ---------------------------------------------------------------------------
# task "message" command [args...]
#
# Runs the command with its output sent to a log file and shows an animated
# [.   ] [..  ] [... ] marker while it runs, then replaces it by [ OK ] or
# [ERROR]. Returns the status of the command; on failure the last lines of the
# log are shown. The command runs in a subshell: variables it sets are lost.
# ---------------------------------------------------------------------------
# A process and all its descendants (apt starts dpkg, cargo starts rustc, ...).
_ui_tree() {
    local child
    echo "$1"
    for child in $(pgrep -P "$1" 2>/dev/null); do _ui_tree "$child"; done
}

_ui_kill_tree() {
    local pids
    pids="$(_ui_tree "$1")"
    # shellcheck disable=SC2086
    kill $pids 2>/dev/null || true
}

_ui_cleanup() {
    if [ "$_UI_CURSOR_HIDDEN" = 1 ]; then printf '\033[?25h'; _UI_CURSOR_HIDDEN=0; fi
}

_task_logfile() {
    local slug
    slug="$(printf '%s' "$1" | tr -c 'A-Za-z0-9' '-' | tr -s '-' | sed 's/^-//; s/-$//' | cut -c1-48)"
    printf '%s/%s.log' "${TPF_LOG_DIR:-${TMPDIR:-/tmp}}" "${slug:-task}"
}

# spin_run LABEL LOGFILE command [args...]
# The running marker alone: the command's output goes to LOGFILE, the marker
# is erased when it ends, nothing else is printed. Returns the command's status.
spin_run() {
    local label="$1" log="$2" rc=0 i=0
    shift 2
    mkdir -p "$(dirname "$log")" 2>/dev/null || true
    if _ui_animated; then
        "$@" >"$log" 2>&1 </dev/null &
        _TASK_PID=$!
        printf '\033[?25l'; _UI_CURSOR_HIDDEN=1
        while kill -0 "$_TASK_PID" 2>/dev/null; do
            printf '\r\033[K%s%s%s %s' "$C_INFO" "${_UI_FRAMES[i % ${#_UI_FRAMES[@]}]}" "$C_RESET" "$label"
            i=$((i + 1))
            sleep 0.15
        done
        wait "$_TASK_PID"; rc=$?
        _TASK_PID=""
        printf '\r\033[K'
        _ui_cleanup
    else
        _ui_line "$C_INFO" '[ .. ]' "$label"
        "$@" >"$log" 2>&1 </dev/null; rc=$?
    fi
    return "$rc"
}

task() {
    local msg="$1" log rc=0 started=$SECONDS took=""
    shift
    [ -z "${TPF_LOG_DIR:-}" ] || mkdir -p "$TPF_LOG_DIR" 2>/dev/null || true
    log="$(_task_logfile "$msg")"
    spin_run "$msg" "$log" "$@" || rc=$?
    [ $((SECONDS - started)) -lt 2 ] || took=" ${C_DIM}($((SECONDS - started))s)${C_RESET}"
    if [ "$rc" -eq 0 ]; then
        _ui_line "$C_OK" '[ OK ]' "$msg$took"
        _ui_log OK "$msg"
    else
        _ui_line "$C_ERR" '[ERROR]' "$msg (exit $rc)$took" >&2
        _ui_log ERROR "$msg (exit $rc)"
        if [ -s "$log" ]; then
            tail -n 8 "$log" | sed "s/^/       ${C_DIM}/; s/\$/${C_RESET}/" >&2
            printf '       %sFull log: %s%s\n' "$C_DIM" "$log" "$C_RESET" >&2
        fi
    fi
    return "$rc"
}
# --- tpf: end src/lib/ui.sh ---

have()    { command -v "$1" >/dev/null 2>&1; }
is_uint() { case "${1:-}" in '' | *[!0-9]*) return 1 ;; esac; }
is_port() { is_uint "${1:-}" && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }

require_termux() {
    case "${PREFIX:-}" in
        *com.termux*) ;;
        *) die "This script must be run inside Termux." ;;
    esac
    [ -n "${HOME:-}" ] || die "\$HOME is not set."
}

require_aarch64() {
    case "$(uname -m)" in
        aarch64 | arm64) ;;
        *) die "Only 64-bit ARM (aarch64) is supported (this device: $(uname -m))." ;;
    esac
}

# ---------------------------------------------------------------------------
# Clean exit. Register cleanup commands with on_exit; they run in reverse
# order when the script ends, whatever the reason (end, die, Ctrl-C).
# ---------------------------------------------------------------------------
_TPF_EXIT_CMDS=()

on_exit() { _TPF_EXIT_CMDS+=("$1"); }

_tpf_exit() {
    local status=$? i
    trap - EXIT
    if [ -n "${_TASK_PID:-}" ]; then _ui_kill_tree "$_TASK_PID"; fi
    _ui_cleanup
    for ((i = ${#_TPF_EXIT_CMDS[@]} - 1; i >= 0; i--)); do
        eval "${_TPF_EXIT_CMDS[i]}" || true
    done
    exit "$status"
}

_tpf_signal() {   # name status
    printf '\n' >&2
    err "Interrupted ($1)."
    exit "$2"
}

trap _tpf_exit EXIT
trap '_tpf_signal INT 130' INT
trap '_tpf_signal TERM 143' TERM

# wake_lock: keep Android from suspending Termux until the script ends.
_TPF_WAKE=0
wake_lock() {
    [ "$_TPF_WAKE" = 0 ] || return 0
    if have termux-wake-lock && termux-wake-lock >/dev/null 2>&1; then
        _TPF_WAKE=1
        on_exit 'termux-wake-unlock >/dev/null 2>&1'
    fi
    return 0
}
# --- tpf: end src/lib/core.sh ---

say()  { echo -e "$*"; }

write_default_conf() {
    ( umask 077; cat > "$CONF" <<EOF
# Settings for code-server.sh — edit, then run: ./code-server.sh restart
CS_PORT=8080
CS_IP=127.0.0.1
# none | password
CS_AUTH=none
CS_PASSWORD=""
# Log lines shown when start-up fails
CS_LOG_LINES=25
# Maximum seconds to wait at start-up
CS_START_TIMEOUT=45
# Start attempts before giving up
CS_START_RETRIES=2
CS_BIN=""
CS_LOG_FILE="\$HOME/.code-server.log"
CS_PID_FILE="\$HOME/.code-server.pid"
CS_CONFIG_DIR="\${XDG_CONFIG_HOME:-\$HOME/.config}/code-server"
CS_DATA_DIR="\${XDG_DATA_HOME:-\$HOME/.local/share}/code-server"
CS_LINUX_SPOOF=0
CS_MS_MARKETPLACE=0
CS_ROOT_INOTIFY=0
CS_INOTIFY_WATCHES=524288
CS_ROOT_HELPER=""
CS_EXTRA_ARGS=""
EOF
    )
    warn "Settings file created with default values: $CONF"
}

[ -f "$CONF" ] || write_default_conf
# shellcheck disable=SC1090
. "$CONF" || { err "Cannot read the settings file: $CONF"; exit 1; }

# --- Validation: a typo must never silently weaken security ----------------
if ! is_uint "$CS_PORT" || [ "$CS_PORT" -lt 1 ] || [ "$CS_PORT" -gt 65535 ]; then
    err "CS_PORT must be a number between 1 and 65535 (got '$CS_PORT') in $CONF"; exit 1
fi
case "$CS_AUTH" in
    none|password) ;;
    *) err "CS_AUTH must be 'none' or 'password' (got '$CS_AUTH') in $CONF"; exit 1 ;;
esac
case "$CS_IP" in
    ''|*:*|*[[:space:]]*) err "CS_IP must be an IPv4 address or a host name (got '$CS_IP') in $CONF"; exit 1 ;;
esac
fix_number() {   # $1 = variable name, $2 = default, $3 = minimum
    local v="${!1}"
    if ! is_uint "$v" || [ "$v" -lt "$3" ]; then
        warn "$1='$v' is invalid in $CONF: $2 used."
        printf -v "$1" '%s' "$2"
    fi
}
fix_number CS_LOG_LINES 25 0
fix_number CS_START_TIMEOUT 45 1
fix_number CS_START_RETRIES 2 1

CONFIG_FILE="$CS_CONFIG_DIR/config.yaml"
SPOOF_FILE="$CS_CONFIG_DIR/android-as-linux.js"

BIN="$CS_BIN"
{ [ -n "$BIN" ] && [ -x "$BIN" ]; } || BIN="$(command -v code-server 2>/dev/null)"

CHECK_HOST="$CS_IP"
[ "$CS_IP" = "0.0.0.0" ] && CHECK_HOST="127.0.0.1"
URL="http://$CHECK_HOST:$CS_PORT/"

# --- Processes -------------------------------------------------------------
# Strict pattern: `pkill -f code-server` would also kill this script.
CS_PROC_PATTERN='code-server([[:space:]]|$)|code-server/out/node/entry'

is_cs_pid() {
    local pid="${1:-}" cmd
    is_uint "$pid" || return 1
    [ -r "/proc/$pid/cmdline" ] || return 1
    cmd="$(tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null)"
    printf '%s\n' "$cmd" | grep -Eq "$CS_PROC_PATTERN"
}

server_pid() {
    local pid
    if [ -s "$CS_PID_FILE" ]; then
        pid="$(cat "$CS_PID_FILE" 2>/dev/null)"
        is_cs_pid "$pid" && { echo "$pid"; return 0; }
    fi
    for pid in $(pgrep -f "$CS_PROC_PATTERN" 2>/dev/null); do
        [ "$pid" = "$$" ] && continue
        [ "$pid" = "${PPID:-0}" ] && continue
        is_cs_pid "$pid" && { echo "$pid"; return 0; }
    done
    return 1
}

pid_tree() {
    local p
    echo "$1"
    for p in $(pgrep -P "$1" 2>/dev/null); do pid_tree "$p"; done
}

stop_pid() {
    local pids p i alive=""
    pids="$(pid_tree "$1")"
    # shellcheck disable=SC2086
    kill -TERM $pids 2>/dev/null
    for i in 1 2 3 4 5; do
        alive=""
        for p in $pids; do kill -0 "$p" 2>/dev/null && alive="$alive $p"; done
        [ -z "$alive" ] && return 0
        sleep 1
    done
    # shellcheck disable=SC2086
    kill -KILL $alive 2>/dev/null
    sleep 1
    for p in $alive; do kill -0 "$p" 2>/dev/null && return 1; done
    return 0
}

# --- Helpers ---------------------------------------------------------------
http_code() {
    # --noproxy: a proxy set in the environment must not intercept localhost.
    curl -s --noproxy '*' -o /dev/null -w '%{http_code}' --max-time 3 "$URL" 2>/dev/null
}

gen_password() {
    if command -v openssl >/dev/null 2>&1; then
        openssl rand -hex 16
    else
        od -An -tx1 -N16 /dev/urandom | tr -d ' \n'
    fi
}

# Generates a password when CS_AUTH=password and none is set, and saves it.
ensure_password() {
    [ "$CS_AUTH" = "password" ] || return 0
    [ -z "$CS_PASSWORD" ] || return 0
    CS_PASSWORD="$(gen_password)"
    if grep -q '^CS_PASSWORD=' "$CONF"; then
        ( umask 077; sed "s|^CS_PASSWORD=.*|CS_PASSWORD=\"$CS_PASSWORD\"|" "$CONF" > "$CONF.tmp" ) \
            && mv -f "$CONF.tmp" "$CONF"
    else
        echo "CS_PASSWORD=\"$CS_PASSWORD\"" >> "$CONF"
    fi
    ok "Password generated and saved in $CONF"
}

# Escapes a value for a double-quoted YAML string.
yaml_escape() { local s="${1//\\/\\\\}"; printf '%s' "${s//\"/\\\"}"; }

# code-server's config.yaml is generated from the settings file.
write_code_server_config() {
    mkdir -p "$CS_CONFIG_DIR" || return 1
    (
        umask 077
        {
            echo "bind-addr: $CS_IP:$CS_PORT"
            if [ "$CS_AUTH" = "password" ]; then
                echo "auth: password"
                echo "password: \"$(yaml_escape "$CS_PASSWORD")\""
            else
                echo "auth: none"
            fi
            echo "cert: false"
        } > "$CONFIG_FILE.tmp"
    ) && mv -f "$CONFIG_FILE.tmp" "$CONFIG_FILE"
}

apply_environment() {
    command -v termux-wake-lock >/dev/null 2>&1 && termux-wake-lock >/dev/null 2>&1

    if [ "${CS_ROOT_INOTIFY:-0}" = "1" ]; then
        if [ "$(id -u)" = "0" ]; then
            echo "$CS_INOTIFY_WATCHES" > /proc/sys/fs/inotify/max_user_watches 2>/dev/null
        elif [ -n "$CS_ROOT_HELPER" ] && [ -x "$CS_ROOT_HELPER" ]; then
            "$CS_ROOT_HELPER" -c "echo $CS_INOTIFY_WATCHES > /proc/sys/fs/inotify/max_user_watches" >/dev/null 2>&1
        fi
    fi

    if [ "${CS_LINUX_SPOOF:-0}" = "1" ] && [ -f "$SPOOF_FILE" ]; then
        export NODE_OPTIONS="--require $SPOOF_FILE ${NODE_OPTIONS:-}"
    fi

    if [ "${CS_MS_MARKETPLACE:-0}" = "1" ]; then
        export EXTENSIONS_GALLERY='{"serviceUrl":"https://marketplace.visualstudio.com/_apis/public/gallery","itemUrl":"https://marketplace.visualstudio.com/items","resourceUrlTemplate":"https://{publisher}.vscode-unpkg.net/{publisher}/{name}/{version}/{path}","controlUrl":"","recommendationsUrl":""}'
    fi
}

# True when this script runs inside code-server's own terminal.
in_code_server_terminal() {
    [ -n "${VSCODE_IPC_HOOK_CLI:-}" ] || [ "${TERM_PROGRAM:-}" = "vscode" ]
}

# --- Commands --------------------------------------------------------------
cmd_start() {
    local pid attempt code deadline
    if [ -z "$BIN" ]; then
        err "code-server not found. Run the install script again."
        exit 1
    fi
    command -v curl >/dev/null 2>&1 || { err "curl is required: pkg install curl"; exit 1; }

    if pid="$(server_pid)"; then
        say "code-server is already running (PID $pid) — $URL"
        exit 0
    fi
    rm -f "$CS_PID_FILE" 2>/dev/null

    code="$(http_code)"
    if [ -n "$code" ] && [ "$code" != "000" ]; then
        err "Another program already answers on $CHECK_HOST:$CS_PORT (HTTP $code)."
        err "Stop it, or change CS_PORT in $CONF."
        exit 1
    fi

    ensure_password
    write_code_server_config || { err "Cannot write $CONFIG_FILE"; exit 1; }
    apply_environment

    # Claude Code support: wrap the extension's binary now, and keep watching
    # while the server runs (the extension may download a new binary).
    if [ -x "$CS_CONFIG_DIR/claude-wrap-binary.sh" ]; then
        "$CS_CONFIG_DIR/claude-wrap-binary.sh" --once >/dev/null 2>&1
        pgrep -f 'claude-wrap-binary.sh --watch' >/dev/null 2>&1 || \
            nohup "$CS_CONFIG_DIR/claude-wrap-binary.sh" --watch >/dev/null 2>&1 </dev/null &
    fi

    if [ "$CS_AUTH" = "none" ] && [ "$CS_IP" != "127.0.0.1" ] && [ "$CS_IP" != "localhost" ]; then
        warn "No authentication and listening on $CS_IP: open to the whole local network."
    fi

    attempt=1
    while [ "$attempt" -le "$CS_START_RETRIES" ]; do
        [ "$attempt" -gt 1 ] && warn "Retrying start-up ($attempt/$CS_START_RETRIES)..."
        [ -f "$CS_LOG_FILE" ] && mv -f "$CS_LOG_FILE" "$CS_LOG_FILE.1" 2>/dev/null

        # Variables that code-server reads from the environment, and which
        # would override the settings file, are removed.
        # shellcheck disable=SC2086
        env -u PORT -u PASSWORD -u HASHED_PASSWORD -u CODE_SERVER_HOST -u VSCODE_IPC_HOOK_CLI \
            nohup "$BIN" --config "$CONFIG_FILE" --user-data-dir "$CS_DATA_DIR" $CS_EXTRA_ARGS \
            >"$CS_LOG_FILE" 2>&1 </dev/null &
        pid=$!
        echo "$pid" > "$CS_PID_FILE"

        deadline=$((SECONDS + CS_START_TIMEOUT))
        while [ "$SECONDS" -lt "$deadline" ]; do
            kill -0 "$pid" 2>/dev/null || break
            code="$(http_code)"
            case "$code" in 200|302|303|401)
                ok "code-server started (PID $pid)"
                say "  URL      : $URL"
                if [ "$CS_AUTH" = "password" ]; then
                    say "  Password : $CS_PASSWORD"
                else
                    say "  Auth     : none"
                fi
                say "  Log      : $CS_LOG_FILE   (./code-server.sh log)"
                exit 0 ;;
            esac
            sleep 1
        done

        stop_pid "$pid"
        rm -f "$CS_PID_FILE" 2>/dev/null
        attempt=$((attempt+1))
    done

    err "code-server did not start after $CS_START_RETRIES attempt(s)."
    say "Last $CS_LOG_LINES lines of $CS_LOG_FILE:"
    tail -n "$CS_LOG_LINES" "$CS_LOG_FILE" 2>/dev/null | sed 's/^/    /'
    exit 1
}

cmd_stop() {
    local pid stopped=0 tries=0
    while pid="$(server_pid)"; do
        tries=$((tries+1))
        if [ "$tries" -gt 5 ]; then
            err "Could not stop code-server (PID $pid)."
            return 1
        fi
        stop_pid "$pid" || warn "PID $pid did not stop yet."
        stopped=1
    done
    rm -f "$CS_PID_FILE" 2>/dev/null
    command -v termux-wake-unlock >/dev/null 2>&1 && termux-wake-unlock >/dev/null 2>&1
    if [ "$stopped" = "1" ]; then ok "code-server stopped."; else say "code-server was not running."; fi
    return 0
}

cmd_restart() {
    # Inside code-server's terminal, stopping the server also kills this
    # terminal — and this script with it. The restart then continues as a
    # detached background process.
    if [ "${1:-}" != "--detached" ] && in_code_server_terminal; then
        warn "Running inside code-server's terminal: the restart continues in the background."
        say "Reload the browser page in a few seconds. Output: $CS_LOG_FILE.restart"
        nohup "$SELF" restart --detached >"$CS_LOG_FILE.restart" 2>&1 </dev/null &
        disown 2>/dev/null || true
        exit 0
    fi
    cmd_stop || exit 1
    sleep 1
    cmd_start
}

cmd_status() {
    local pid
    if pid="$(server_pid)"; then
        ok "code-server is running (PID $pid) — $URL"
        exit 0
    fi
    say "code-server is not running."
    exit 3
}

cmd_log() {
    local n="${1:-50}"
    is_uint "$n" || { err "The number of lines must be a positive number (got '$n')."; exit 2; }
    [ -f "$CS_LOG_FILE" ] || { err "No log yet: $CS_LOG_FILE"; exit 1; }
    exec tail -n "$n" -f "$CS_LOG_FILE"
}

cmd_help() {
    cat <<EOF
Usage: ./code-server.sh <command>

  start        Start code-server (re-reads $CONF)
  stop         Stop code-server
  restart      Restart it
  status       Tell whether it is running
  log [n]      Follow the log, last n lines (default 50)
  help         This help

Settings: $CONF
  CS_PORT=$CS_PORT   CS_IP=$CS_IP   CS_AUTH=$CS_AUTH
EOF
}

case "${1:-help}" in
    start)          cmd_start ;;
    stop)           cmd_stop ;;
    restart)        cmd_restart "${2:-}" ;;
    status)         cmd_status ;;
    log|logs)       cmd_log "${2:-50}" ;;
    help|-h|--help) cmd_help ;;
    *)              err "Unknown command: $1"; cmd_help; exit 2 ;;
esac
